import{_ as a,c as t,o,ae as l}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Stackable Table","description":"Stackable Table","frontmatter":{"title":"Stackable Table","description":"Stackable Table"},"headers":[],"relativePath":"guide/responsive-design/stackable-table.md","filePath":"guide/responsive-design/stackable-table.md"}'),s={name:"guide/responsive-design/stackable-table.md"};function n(i,e,r,c,b,d){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="stackable-table" tabindex="-1">Stackable Table <a class="header-anchor" href="#stackable-table" aria-label="Permalink to &quot;Stackable Table&quot;">​</a></h1><p>Ninja Tables has a unique function where you can stack table rows on top of one another. This <strong>Stackable Table</strong> feature has contributed to Ninja Tables becoming even more user-friendly and responsive. Stackable Table allows you to break down each row of any table into individual tables. It results in a stacked table arrangement that is compatible with all types of devices. This easy guide explains to you how to quickly and easily build up stackable tables! Note that Stackable Table and <a href="https://ninjatables.com/docs/column-responsive-breakpoints/" target="_blank" rel="noreferrer">Responsive Breakpoint</a> will not work together. Either you can use Stackable features or Responsive Breakpoints.</p><ul><li>Click the Table Design tab placed at the top of the table you want to use the stackable features on.</li><li>Then at the bottom of the Styling tab, you will notice the <strong>Stackable Table Configuration</strong> option. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Stackable-Table-1-1-scaled.webp" alt="Table Design tab"></li><li>Now, select the <strong>Enable Stackable Table</strong> checkbox. Once this step is done, the <strong>Target Devices</strong> option will appear.</li><li>And make sure you click the <strong>Update Settings</strong> button to save the changes. Here you can choose your table to be displayed in a stacked format on various devices that suit your requirements, as shown below - <img src="https://ninjatables.com/wp-content/uploads/2022/09/Stackable-Table-2-scaled.webp" alt="Target Device Option"></li><li>Given below is an example of a Product Listing table after enabling a stackable table on a <strong>Tablet Device</strong>.</li><li>You will notice that separate tables have been generated in a stacked layout from individual rows. To adjust the columns in this device width, the row header &amp; content are placed on the left &amp; right side, respectively. This step is similarly applicable to mobile, laptop, and desktop devices. <img src="https://ninjatables.com/wp-content/uploads/2023/01/stackable-table-4.png" alt="stackable product listing table"></li><li>Stackable tables can also customize the appearance of a stacked view of your table. Following the screenshot below, click on the <strong>Hide Column Headings</strong> located under the <strong>Stacked Appearance</strong> option. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Stackable-Table-3-scaled.webp" alt="Hide Column Settings"></li><li>You can hide column headings or internal borders from here. This is how easy it is to configure <strong>Stackable</strong> <strong>table</strong> <strong>format</strong> in your Ninja** **tables!</li></ul>',3)])])}const h=a(s,[["render",n]]);export{u as __pageData,h as default};
